# Алгоритмы звонков — дословно из файлов Лили. Ничего не добавлено и не сокращено.
from shell import *

P = {}

def h(t): return f'<h2>{t}</h2>'
def p(t): return f'<p>{t}</p>'
def q(t): return f'<div class="say">{t}</div>'
def li(*items): return '<ul class="l">' + ''.join(f'<li>{i}</li>' for i in items) + '</ul>'
def lab(t): return f'<div class="label" style="color:var(--text);font-weight:600;font-size:13px">{t}</div>'
def box(t, cls=''): return f'<div class="box {cls}">{t}</div>'
def page_head(title, sub=''):
    return f'<a class="back" href="razdel-zvonki.html">← Звонки</a><div class="head"><h1>{title}</h1>' + (f'<p>{sub}</p>' if sub else '') + '</div>'

SUPPORT_BLOCK = (
    p('Перед звонком: посмотреть обращения и понять, насколько они актуальны (свежие / старые)') +
    q('«Вижу, что вы обращались по вопросу [тема], коллеги помогли. Подскажите, всё ли было понятно?»') +
    q('«Вижу, что у вас есть вопрос по [тема]. Я уточню у коллег и вернусь к вам с обратной связью»') +
    q('«Вижу, что вы уже обратились в поддержку, коллеги занимаются вашим вопросом. Я со своей стороны проконтролирую»') +
    box('<b>Важно:</b> не дублируем поддержку, не уходим в технические детали, не решаем вопрос самостоятельно', 'warn'))

